const rows = $('Load Queued Videos').all().map(i => i.json || {});
const products = $('Load Products For Packshot').all().map(i => i.json || {});
const queuedRows = rows.filter(r => r.approval_status === 'approved' && r.render_status === 'queued');
const target = queuedRows[queuedRows.length - 1] || rows[rows.length - 1];
if (!target || !target.video_key) return [];

const matchedProd = products.find(p => p.product_key === target.product_key) || {};
const dePackshotUrl = String(matchedProd.packshot_image_url || '');
const refVideoUrl = String(target.final_video_url || '');
const productName = String(matchedProd.product_name || target.product_key || '').slice(0, 140);

let scenes = [];
try { scenes = JSON.parse(target.scenes_json || '[]'); } catch (e) { scenes = []; }
const m = refVideoUrl.match(/^https:\/\/api\.apify\.com\/v2\/key-value-stores\/([^/]+)\/records\/([^?]+)/i);
if (!scenes.length || !m) {
  return [{ json: { __blocked: true, __target: target, __de_packshot: dePackshotUrl, video_key: target.video_key, render_status: 'blocked_no_reference', lookup_url: '' } }];
}
const lookup_url = 'https://api.apify.com/v2/key-value-stores/' + m[1] + '/keys?limit=1&prefix=' + encodeURIComponent(decodeURIComponent(m[2]));
return [{ json: { __target: target, __de_packshot: dePackshotUrl, product_name: productName, lookup_url } }];

const inputItems = $input.all().map(i => i.json || {});
// Blocked path (Has Reference Lookup false, or Emit Scene Frames blocked): mark row, no judge needed.
if (inputItems.length && inputItems[0].__blocked) {
  return [{ json: { ...inputItems[0].__target, render_status: 'blocked_no_reference', vision_rejections_json: '[]' } }];
}
const verdictItems = inputItems;
const sceneItems = $('Emit Scene Frames').all().map(i => i.json || {});
if (!sceneItems.length || !sceneItems[0].__target) return [];
const first = sceneItems[0];
const target = first.__target;
const dePackshotUrl = first.__de_packshot || '';

const good = [];
const rejected = [];
sceneItems.forEach((s, i) => {
  const j = verdictItems[i] || {};
  const ref = { ref_scene_no: s.ref_scene_no, reference_clip_url: s.reference_clip_url, ref_start_sec: s.ref_start_sec, ref_end_sec: s.ref_end_sec, frame_url: s.frame_url || '' };
  const content = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
  const m = String(content).match(/\{[\s\S]*\}/);
  let ok = false, zone = 'none', reason = 'vision_error';
  try {
    const v = m ? JSON.parse(m[0]) : null;
    ok = !!(v && v.ok);
    zone = v && v.overlay_zone ? String(v.overlay_zone).toLowerCase() : 'none';
    reason = v && v.reason ? String(v.reason) : (j.choices ? 'unparseable' : 'vision_error');
  } catch (e) { reason = 'unparseable'; }
  // SOFTENED GATE: accept real product footage with overlays ONLY in bottom third
  if (ok && (zone === 'none' || zone === 'bottom')) {
    ref.cover_overlay = zone === 'bottom';
    good.push(ref);
  } else {
    rejected.push({ scene_no: s.ref_scene_no, reason: ok ? 'overlay_' + zone : reason });
  }
});

let scenes = [];
try { scenes = JSON.parse(target.scenes_json || '[]'); } catch (e) { scenes = []; }
if (!scenes.length || good.length < 2) {
  return [{ json: { ...target, render_status: 'blocked_no_reference', vision_rejections_json: JSON.stringify(rejected) } }];
}

const lastIdx = scenes.length - 1;
const enrichedScenes = scenes.map((s, i) => {
  const isLast = i === lastIdx && scenes.length > 1;
  if (isLast) return { ...s, ref_scene_no: null, reference_clip_url: '', generated_clip_url: '', generated_image_url: dePackshotUrl || s.generated_image_url || '' };
  if (i < good.length) {
    const pick = good[i];
    return { ...s, ref_scene_no: pick.ref_scene_no, reference_clip_url: pick.reference_clip_url, ref_start_sec: pick.ref_start_sec, ref_end_sec: pick.ref_end_sec, vision_verdict: pick.cover_overlay ? 'ok_bottom_overlay' : 'ok', cover_overlay: !!pick.cover_overlay, generated_clip_url: pick.reference_clip_url, generated_image_url: pick.frame_url || dePackshotUrl || '' };
  }
  return { ...s, ref_scene_no: null, reference_clip_url: '', vision_verdict: 'packshot_fallback', generated_clip_url: '', generated_image_url: dePackshotUrl || s.generated_image_url || '' };
});

return [{ json: { ...target, scenes_json: JSON.stringify(enrichedScenes), reference_audio_url: first.__audio_url || '', vision_stats: 'usable=' + good.length + '/' + sceneItems.length, vision_rejections_json: JSON.stringify(rejected), render_status: 'ready_for_ffmpeg' } }];

const sel = $('Analyze Reference Scenes').first().json || {};
const target = sel.__target || {};
const items = ($('Resolve Ref Public URL').first().json.data || {}).items || [];
const signed = (items.find(i => i.recordPublicUrl) || {}).recordPublicUrl || '';
if (!signed) {
  return [{ json: { __blocked: true, __target: target, __de_packshot: sel.__de_packshot || '', video_key: target.video_key, render_status: 'blocked_no_reference' } }];
}
let analysis = null;
try {
  analysis = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://ffmpeg.mafrapi.eu/api/ffmpeg/analyze-reference',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ videoUrl: signed }),
    timeout: 120000
  });
} catch (e) { analysis = null; }
const refScenes = (analysis && Array.isArray(analysis.scenes) ? analysis.scenes : [])
  .filter(s => s && s.reference_clip_url && Number(s.duration_sec) >= 2);
if (!refScenes.length) {
  return [{ json: { __blocked: true, __target: target, __de_packshot: sel.__de_packshot || '', video_key: target.video_key, render_status: 'blocked_no_reference' } }];
}
return refScenes.map((s, i) => ({ json: {
  __target: target,
  __de_packshot: sel.__de_packshot || '',
  __audio_url: (analysis && analysis.reference_audio_url) || '',
  __product_name: sel.product_name || '',
  ref_scene_no: i + 1,
  reference_clip_url: s.reference_clip_url,
  ref_start_sec: s.start_sec,
  ref_end_sec: s.end_sec,
  frame_url: (s.frames && s.frames[0] && s.frames[0].url) || ''
} }));
